function rgba(c, alpha) { mgraphics.set_source_rgba(c[0], c[1], c[2], alpha === undefined ? c[3] : alpha); }
function mix(a, b, t) { return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t, 1]; }
